 "<b style=\"font-family:'Merriweather', serif;font-size:30px\">Repetición</b><br>los mismos colores y estilos": "<b style=\"font-family:'Merriweather', serif;font-size:30px\">Répétition</b><br>mêmes couleurs, mêmes styles",
 "<b style=\"font-family:'Merriweather', serif;font-size:30px\">Proximidad</b><br>junto lo que va junto": "<b style=\"font-family:'Merriweather', serif;font-size:30px\">Proximité</b><br>rapprocher ce qui va ensemble",
